<div class="page-actions"><div><p class="muted">Consulta, actualiza y administra la agenda médica.</p></div><?php if(in_array(\App\Core\Auth::role(),['admin','receptionist'],true)):?><a class="btn btn-primary" href="<?= url('/appointments/create') ?>">+ Nueva cita</a><?php endif;?></div>
<div class="panel"><div class="table-tools"><input class="search-input" data-table-search="#appointmentsTable" placeholder="Buscar cita..."><select id="statusFilter" class="compact-select"><option value="">Todos los estados</option><option value="pendiente">Pendiente</option><option value="confirmada">Confirmada</option><option value="atendida">Atendida</option><option value="cancelada">Cancelada</option><option value="no asistió">No asistió</option></select></div><div class="table-wrap"><table id="appointmentsTable"><thead><tr><th>Fecha / hora</th><th>Paciente</th><th>Médico</th><th>Motivo</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($appointments as $a):$label=['pending'=>'Pendiente','confirmed'=>'Confirmada','completed'=>'Atendida','cancelled'=>'Cancelada','no_show'=>'No asistió'][$a['status']]??$a['status'];?><tr><td><strong><?= e(date('d/m/Y',strtotime($a['appointment_date']))) ?></strong><small class="cell-sub"><?= e(substr($a['appointment_time'],0,5)) ?> · <?= e($a['duration_minutes']) ?> min</small></td><td><?= e($a['patient_name']) ?></td><td><?= e($a['doctor_name']) ?><small class="cell-sub"><?= e($a['specialty_name']) ?></small></td><td><?= e($a['reason']) ?></td><td><span class="badge status-<?= e($a['status']) ?>"><?= e($label) ?></span></td><td class="actions"><a class="btn btn-sm" href="<?= url('/appointments/'.$a['id'].'/edit') ?>"><?= \App\Core\Auth::role()==='doctor'?'Actualizar':'Editar' ?></a><?php if(in_array(\App\Core\Auth::role(),['admin','receptionist'],true)):?><form method="post" action="<?= url('/appointments/'.$a['id'].'/delete') ?>" data-confirm="¿Eliminar esta cita?"><?= csrf_field() ?><button class="btn btn-sm btn-danger">Eliminar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
